"""a module for unittest
"""
import os
import threading

from testbase.conf import settings


class _NotExistedItem(object):
    pass


class modify_settings(object):
    """temporarily modify settings

    Loaded settings are sealed and must reject assignment. The seal used to
    stay open after this helper ran, so a later ``settings.X = ...`` was
    accepted or rejected depending on earlier tests in the same process.

    ``__ensure_loaded`` also reloads from disk whenever the seal is open, which
    drops in-memory overrides. Reads therefore happen only while sealed, and
    the loader is suppressed for the short window where this helper itself
    writes. The seal is always closed again before user code runs.
    """

    _lock = threading.RLock()

    def __init__(self, **kwargs):
        self.new_conf = kwargs
        self.old_conf = {}

    def __enter__(self):
        self._ensure_loaded_no_reset()
        for key in self.new_conf:
            self.old_conf[key] = getattr(settings, key, _NotExistedItem())
        try:
            self._write_settings(self._apply_new)
        except Exception:
            # A failed __enter__ does not run __exit__.
            self._write_settings(self._apply_old)
            raise

    def __exit__(self, *args):
        self._write_settings(self._apply_old)

    def _ensure_loaded_no_reset(self):
        # An earlier leak leaves __sealed False. Closing it first makes
        # __ensure_loaded a no-op instead of resetting every value.
        try:
            if settings._Settings__keys and not settings._Settings__sealed:
                settings._Settings__sealed = True
        except AttributeError:
            pass
        settings._Settings__ensure_loaded()  # ensure loaded
        if not settings._Settings__sealed:
            settings._Settings__sealed = True

    def _apply_new(self):
        for key, value in self.new_conf.items():
            if isinstance(self.old_conf.get(key), _NotExistedItem):
                settings._Settings__keys.add(key)
            self._assign(key, value)

    def _apply_old(self):
        keys = settings._Settings__keys
        for key, old_value in list(self.old_conf.items()):
            if isinstance(old_value, _NotExistedItem):
                try:
                    delattr(settings, key)
                except (AttributeError, RuntimeError):
                    try:
                        object.__delattr__(settings, key)
                    except AttributeError:
                        pass
                if key in keys:
                    keys.remove(key)
            else:
                self._assign(key, old_value)
        self.old_conf.clear()

    def _assign(self, key, value):
        try:
            setattr(settings, key, value)
        except RuntimeError:
            # Seal check still tripped (loader re-sealed, or setattr refuses
            # while sealed). Write the instance dict directly.
            object.__setattr__(settings, key, value)
            if key not in settings._Settings__keys:
                settings._Settings__keys.add(key)

    def _write_settings(self, callback):
        """Run callback with the seal open and reload suppressed."""
        cls = type(settings)
        loaded_name = "_Settings__ensure_loaded"
        original_loader = getattr(cls, loaded_name, None)

        def _noop(_self):
            return None

        with self._lock:
            if original_loader is not None:
                setattr(cls, loaded_name, _noop)
            try:
                settings._Settings__sealed = False
                try:
                    callback()
                finally:
                    # Read-only again before returning to the with-body or the
                    # caller, including when restore itself fails.
                    settings._Settings__sealed = True
            finally:
                if original_loader is not None:
                    setattr(cls, loaded_name, original_loader)


