import os
import threading

from testbase.conf import settings


class _NotExistedItem(object):
    pass


# Assignment is rejected only after __sealed is set, and that flag stays false
# until something has loaded settings. It also stays false if modify_settings
# opened it and did not put it back. Either way a later `settings.X = ...`
# is stored or raises depending on earlier work in this process.
_tls = threading.local()


def _flag(name):
    return getattr(_tls, name, 0)


def _set_flag(name, value):
    setattr(_tls, name, value)


def _sealed(obj):
    try:
        return bool(object.__getattribute__(obj, "_Settings__sealed"))
    except AttributeError:
        return False


def _keys(obj):
    try:
        return object.__getattribute__(obj, "_Settings__keys")
    except AttributeError:
        return None


def _install_readonly_guard():
    cls = type(settings)
    if getattr(cls, "_qtaf_readonly_guard", False):
        return
    orig_setattr = cls.__setattr__
    orig_delattr = cls.__delattr__
    orig_ensure = cls._Settings__ensure_loaded

    def guarded_ensure(self):
        # _load() writes each item through __setattr__ while still unsealed.
        # Re-entering here would treat those writes as user assignments.
        if _flag("loading"):
            return
        _set_flag("loading", 1)
        try:
            return orig_ensure(self)
        finally:
            _set_flag("loading", 0)

    def _reject_unless_loader(self, name, write):
        if (
            (isinstance(name, str) and name.startswith("_Settings__"))
            or _flag("loading")
            or _flag("bypass")
        ):
            return write()
        if not _sealed(self):
            if not _keys(self):
                guarded_ensure(self)
            # Loaded (or just loaded) settings are immutable. A leaked open
            # seal must not keep accepting writes.
            if not _sealed(self):
                object.__setattr__(self, "_Settings__sealed", True)
        return write()

    def guarded_setattr(self, name, value):
        return _reject_unless_loader(
            self, name, lambda: orig_setattr(self, name, value)
        )

    def guarded_delattr(self, name):
        return _reject_unless_loader(self, name, lambda: orig_delattr(self, name))

    cls._Settings__ensure_loaded = guarded_ensure
    cls.__setattr__ = guarded_setattr
    cls.__delattr__ = guarded_delattr
    cls._qtaf_readonly_guard = True


_install_readonly_guard()


