            self.old_conf[key] = getattr(settings, key, _NotExistedItem())
        try:
            self._rewrite(self.new_conf, restore=False)
        except Exception:
            self.__exit__(None, None, None)
            raise

    def __exit__(self, *args):
        self._rewrite(self.old_conf, restore=True)

    def _ensure_loaded(self):
        keys = _keys(settings)
        if keys and not _sealed(settings):
            # Already populated; do not reload by calling __ensure_loaded.
            object.__setattr__(settings, "_Settings__sealed", True)
            return
        settings._Settings__ensure_loaded()  # ensure loaded
